\begin{theorem}\label{night:P1.3}
\StatementRecord{night:P1.3}{proved}{}{Definitions and the displayed constructions}
The two finite filling pieces have first integral homology
$\mathbb Z^2$ and $\mathbb Z^2\oplus\mathbb Z/2$.
\end{theorem}

\begin{theorem}\label{night:P1.10}
\StatementRecord{night:P1.10}{proved}{}{\cref{night:P1.11}, \cref{night:P1.9}}
For every real parameter $c>-h_{\min}$ the corrected construction gives
a compact smooth complex fourfold $M_c$ and a proper holomorphic map
to $\mathbb P^1$ with the two specified multiple fibres and the
index-one Kuhn cusp.  With its complex orientation,
$\pi_1(M_c)=1$ and $\chi(M_c)=6$.
\end{theorem}

\begin{theorem}\label{night:P1.11}
\StatementRecord{night:P1.11}{proved}{}{\cref{night:P1.9}}
The index-one central cusp fibre $C$ has torsion-free integral homology
with ranks $(1,3,9,9,10,3,1)$.
The collapse $\kappa:T^6\to C$ has primitive image in every degree;
it is onto except in degree four, where its cokernel is $\mathbb Z$.
Its image ranks are $(1,3,9,9,9,3,1)$.
In every degree its kernel is the saturation of
$(\bigwedge^kM_0-I)\bigwedge^k\Lambda$.
\end{theorem}

\begin{theorem}\label{night:P1.12}
\StatementRecord{night:P1.12}{proved}{}{\cref{night:P1.1}, \cref{night:P1.9}, \cref{night:P1.10}, \cref{night:P1.11}; the actual marked evaluation and finite logarithmic collar maps; \cite[Theorem 4.1.1 and Lemmas 4.1.2--4.1.3, pp.~480--482]{ffAchingerOgus20}; \cite[Theorem 3.2, p.~195; Theorem 3.30, p.~241; Theorem 4.32, p.~366]{Hatcher2002}}
The fourfold $M_c$ has torsion-free integral homology
\[
H_k(M_c;\mathbb Z)=
\begin{cases}
\mathbb Z,&k=0,8,\\
\mathbb Z^4,&k=4,\\
0,&k=1,2,3,5,6,7.
\end{cases}
\]
In particular it is three-connected.
\end{theorem}

\begin{theorem}\label{night:P1.5}
\StatementRecord{night:P1.5}{proved}{}{Definitions and the displayed constructions}
The formula in the prompt with $P$ the image of
$\ell_0\wedge\mathcal H$, and $\mathcal H$ the rank-two Hodge bundle,
cannot produce a rank-three subbundle.  The required rank-three image
is instead the image of $\ell_0\wedge\mathcal H_{\mathrm{dR}}$, where
$\mathcal H_{\mathrm{dR}}$ is the full rank-four de Rham bundle.
\end{theorem}

\begin{theorem}\label{night:P1.2}
\StatementRecord{night:P1.2}{proved}{}{Definitions and the displayed constructions}
The lower blocks of $A,B$ are precisely the quotient representations of
$\bigwedge^2(C_f^{-1}),\bigwedge^2C_g$ in the supplied basis $Q$.
The integral quotient is the dual of the primitive exterior-square
lattice.  The natural map from the primitive lattice into that quotient
has cokernel $\mathbb Z/2$; these two integral representations are not
isomorphic.  Their rationalizations are isomorphic by that same map.
\end{theorem}

\begin{theorem}\label{night:P1.7}
\StatementRecord{night:P1.7}{proved}{}{\cref{maps:src:F.3.5}, \cref{night:P1.2}}
The integral $H^1$ monodromy of the pencil has a companion marking with
finite pair $(C_f^{-1},C_g)$, and cusp product $C_fC_g^{-1}$.
Its exterior-square quotient is consequently the integral quotient
representation appearing in P1.2.
\end{theorem}

\begin{theorem}[a complex structure on the stated connected sum]\label{maps:src:F.4.1}
\StatementRecord{maps:src:F.4.1}{proved}{}{the hypotheses, notation and definitions stated here; \cref{maps:src:F.3.7}; \cref{maps:src:F.2.6}; \S\ref{sec:V-known-inputs}; the explicit integral reflections below; \cite[Corollary 1.4, p.~4]{ffMandal}; \cite[Definition 3.6 and Theorem 3.7(1), pp.~12--14]{IVVWallForm}; \cite[Theorem A, p.~178]{IVVKramerStolz}; \cref{night:P1.13}}


The compact complex fourfold of Theorem \ref{maps:src:F.3.7} is three-connected,
has Euler number six, and is orientation-preservingly diffeomorphic to
\[
 3\mathbb H\mathbb P^2\ \#\ (-\mathbb H\mathbb P^2).
 \tag{F.25}\label{maps:eq:F.25}
\]
Its integral middle lattice is $I_{3,1}$ and, in a diagonal integral
basis, $p_1/2=(1,1,1,1)$.  In particular the conclusion is an exact
smooth diffeomorphism, with no remaining homotopy-sphere ambiguity.

\end{theorem}

\begin{theorem}\label{night:P1.16}
\StatementRecord{night:P1.16}{proved}{}{\cref{night:P1.15}, \cref{night:P1.18}, \cref{night:P1.8}}
In the canonical splitting $\sigma_b$ of P1.15,
\[
\begin{aligned}
-1.0342766224163217994942488453783461&<h_b(1),\\
h_b(1)&<-1.0342766224163217994942488453783460.
\end{aligned}
\]
In particular $h_b(1)<-1$.  The parameter $c=5/(3\pi)$ is outside the
global transversality domain.  The lifted period matrices at
$\lambda=1,2$ have been evaluated by two different continuation methods
agreeing to more than thirty decimal digits.
\end{theorem}

\begin{theorem}\label{night:P1A.2}
\StatementRecord{night:P1A.2}{proved}{}{\cref{night:P1.15}, \cref{night:P1A.1}}
The complete Hodge table of every admissible fourfold is the
following, with rows indexed by $p$ and columns by $q$:
\[
\begin{array}{c|ccccc}
h^{p,q}&0&1&2&3&4\\\hline
0&1&1&0&0&0\\
1&0&2&1&0&0\\
2&0&1&6&1&0\\
3&0&0&1&2&0\\
4&0&0&0&1&1
\end{array}
\]
\end{theorem}

\begin{theorem}\label{night:P1.17}
\StatementRecord{night:P1.17}{proved}{}{\cref{night:P1.1}}
For the cusp marking $S$ fixed in P1.1 and the corresponding Kuhn fan,
none of the completed fourfolds in this family admits an
anti-holomorphic automorphism.  In particular none admits a real
structure.  More strongly, two members with this same cusp marking
are never anti-biholomorphic.
\end{theorem}

\begin{theorem}\label{night:P1A.5}
\StatementRecord{night:P1A.5}{proved}{}{\SeriesRef{night:P2.4}, \cref{night:P1A.1}, \cref{night:P1.8}; \cite[Theorem 1.6, preprint p.~5]{BM97}; \cite[\S6, Hauptsatz I; \S7, Satz 1 and Satz 5]{Grauert60}}
There is no such analytic extension across any finite boundary
point of $\mathcal H$, or across infinity. The same conclusion
holds after any finite ramified change of the local boundary
coordinate. In particular neither end of the real interval
$c_*<c<+\infty$ has a proper Hausdorff analytic extension in
this sense.
\end{theorem}

\begin{theorem}\label{night:P1A.6}
\StatementRecord{night:P1A.6}{proved}{}{\cref{night:P1A.3}, \cref{night:P1A.4}}
A holomorphic punctured-disc family whose fibres are all
members of this fourfold family has an interior parameter
limit. After a base change of degree at most two, it is
isomorphic to the pullback of the constructed family by
a holomorphic map of the full disc to $\mathcal H$, and
therefore has a proper smooth filling. Such a family
cannot approach either parameter end.
\end{theorem}

\begin{theorem}\label{night:P1B.2}
\StatementRecord{night:P1B.2}{proved}{}{Definitions and the displayed constructions}
A finite-order integral linear action on $\R^6$ admitting a
free finite affine torus lift has characteristic polynomial
among exactly thirty-eight cyclotomic products. Their linear
orders are
\[
 1,2,3,4,5,6,8,10,12.
\]
Exactly nineteen of these polynomials admit a commuting complex
structure on $\R^6$. These are a preliminary spectral list;
no assertion about global gluings is inferred from the list.
\end{theorem}
